import urllib.request

url = "https://raw.githubusercontent.com/sddm/sddm/develop/src/daemon/Display.cpp"
try:
    req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
    code = urllib.request.urlopen(req).read().decode("utf-8")
    for line in code.splitlines():
        if "Autologin" in line or "findSession" in line or "session" in line.lower() and "desktop" in line.lower():
            print(line)
except Exception as e:
    print(e)
